#include "glasses_low.cpp"
using Lev5=std::array<int,5>;
Coeff fullfermion(Lev5 lev,S q,int il,int ir){Coeff out{};if(lev[0])return out;FermionForm ff;std::array<std::array<S,2>,2> t{};for(int side=0;side<2;side++){int in=lev[1+2*side]/2,ot=lev[2+2*side]/2,ins=side?ir:il;if(in<0||ot<0||in>1||ot>1||(!ins&&in!=ot))return out;for(int g=0;g<2;g++){int go=(in==ot)?g:1-g,parity=(in+g)%2;AuxState aa{},a{in?Part{1}:Part{},g},c{ot?Part{1}:Part{},go};S value=ff.complex_value<S>({aa,a,c})*S(sign(parity));if(ins)value*=q*((in==ot)?S(sign(g))/root(S(2)):S(sign(g+in)));t[side][parity]+=value;}}for(int a=0;a<2;a++)for(int c=0;c<2;c++)out[(a<<1)|(c<<2)]=t[0][a]*t[1][c];return out;}
int main(){S b=1.4;std::array<S,3>p{11./23,13./29,17./31};std::cout<<std::setprecision(17)<<"{\"split_edge_cutoff\":1,\"precision\":\"machine complex double\",\"cases\":[";bool first=true;int fail=0,total=0;double start=seconds();for(int f=0;f<2;f++)for(int el:{-1,1})for(int er:{-1,1}){int il=sign(f)*el<0,ir=sign(f)*er<0;Physical phy(b,p,f,el,er);DV dv(b,p,f,el,er,il,ir);GlassesSeries physical;for(int bb=0;bb<=2;bb++)for(int l=0;l<=2;l+=2)for(int r=0;r<=2;r+=2)physical[{bb,l,r}]=phy.coefficient({bb,l,r});double err=0,scaled=0;int count=0,offdiag=0;std::vector<std::tuple<Lev5,int,S,S>>bad;for(int bb=0;bb<=2;bb++)for(int li=0;li<=2;li+=2)for(int lo=0;lo<=2;lo+=2)for(int ri=0;ri<=2;ri+=2)for(int ro=0;ro<=2;ro+=2){if((!il&&li!=lo)||(!ir&&ri!=ro))continue;Lev5 lev{bb,li,lo,ri,ro};Coeff expected{};for(auto [aa,ph]:physical){Lev5 auxlev{bb-aa[0],li-aa[1],lo-aa[1],ri-aa[2],ro-aa[2]};if(*std::min_element(auxlev.begin(),auxlev.end())<0)continue;auto ff=fullfermion(auxlev,b+S(1)/b,il,ir);for(int k=0;k<8;k++)expected[k]+=product_entry(ph,ff,f,k);}auto got=dv.full(lev);for(int k=0;k<8;k++){double e=std::abs(got[k]-expected[k]);err=std::max(err,e);double se=e/std::max({1.,std::abs(got[k]),std::abs(expected[k])});scaled=std::max(scaled,se);if(se>1e-9)bad.emplace_back(lev,k,got[k],expected[k]);}count+=8;if(li!=lo||ri!=ro)offdiag+=8;}if(scaled>1e-9)fail++;total+=count;if(!first)std::cout<<",";first=false;std::cout<<"{\"f\":"<<f<<",\"eta_L\":"<<el<<",\"eta_R\":"<<er<<",\"split_loops\":["<<il<<","<<ir<<"],\"components\":"<<count<<",\"offdiagonal_components\":"<<offdiag<<",\"max_absolute_error\":"<<err<<",\"max_scaled_error\":"<<scaled<<",\"failures\":[";bool fb=true;for(auto [lev,k,g,e]:bad){if(!fb)std::cout<<",";fb=false;std::cout<<"{\"level2\":[";for(int i=0;i<5;i++){if(i)std::cout<<",";std::cout<<lev[i];}std::cout<<"],\"parity\":"<<k<<",\"DV\":";complex_json(g);std::cout<<",\"PBW_convolution\":";complex_json(e);std::cout<<"}";}std::cout<<"]}";}
std::cout<<"],\"components\":"<<total<<",\"failed_cases\":"<<fail<<",\"runtime_seconds\":"<<seconds()-start<<"}\n";return fail?1:0;}
